#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {  // Child process
        execl("/bin/sh", "sh", "-c", "ls -l", (char *)0);
        perror("execl failed");  // This line executes only if execl fails
        _exit(1);
    } else if (pid > 0) {  // Parent process
        wait(NULL);  // Wait for child to finish
        printf("Command executed.\n");
    } else {
        printf("Fork failed.\n");
    }
    return 0;
}
